"""
C_generators.py — Structure constant generator for C(n+1) = osp(2|2n).

Computes Schema 1 JSON (algebra structure, basis, parity, generator realization,
structure constants) for bosonic rank n=1, 2, 3.

Mathematical reference: docs/math/Cn1_definition.md
Schema spec: docs/json_schema_specification.md
"""

from fractions import Fraction
from itertools import product
import json
import os
from datetime import date


# ---------------------------------------------------------------------------
# Basis construction
# ---------------------------------------------------------------------------

def build_basis(n):
    """Return ordered basis lists (odd, even) for C(n+1), bosonic rank n."""
    odd = []
    for k in range(1, n + 1):
        odd += [
            f"E_eps1_del{k}_pp",
            f"E_eps1_del{k}_pm",
            f"E_eps1_del{k}_mp",
            f"E_eps1_del{k}_mm",
        ]

    even = [f"H_{k}" for k in range(1, n + 2)]  # H_1 ... H_{n+1}
    for k in range(1, n + 1):
        even += [f"E_2del{k}_p", f"E_2del{k}_m"]
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            even += [
                f"E_del{i}_del{j}_pp",
                f"E_del{i}_del{j}_mm",
                f"E_del{i}_del{j}_pm",
                f"E_del{i}_del{j}_mp",
            ]
    return odd, even


def build_parity(odd, even):
    parity = {}
    for g in odd:
        parity[g] = 1
    for g in even:
        parity[g] = 0
    return parity


# ---------------------------------------------------------------------------
# Generator realization as vectors over oscillator monomials
#
# We represent each generator as a dict: monomial_tuple -> Fraction coefficient.
# Monomial tuples use the PBW order over oscillator letters:
#   a1p, a1m, b1p, b1m, b2p, b2m, ...
# Each letter appears 0 or 1 time (fermionic) or 0,1,2 times (bosonic).
#
# For structure constants we use the Lie superalgebra bracket computed via
# the oscillator algebra:  [XY] = XY - (-1)^{p(X)p(Y)} YX,
# plus the CAR relation  a1m*a1p = 1 - a1p*a1m (i.e. {a1m,a1p}=1)
# and CCR relations      bim*bjp = delta_{ij} + bjp*bim.
# ---------------------------------------------------------------------------

def osc_labels(n):
    """Ordered oscillator labels."""
    return ["a1p", "a1m"] + [f"b{k}p" if s == "p" else f"b{k}m"
                              for k in range(1, n + 1)
                              for s in ["p", "m"]]


def osc_parity(label):
    return 1 if label.startswith("a") else 0


def monomial_parity(mon):
    return sum(osc_parity(l) for l in mon) % 2


def normal_order(mon, n):
    """
    Reduce a monomial (tuple of oscillator labels) to normal-ordered form
    using CAR/CCR relations. Returns dict: tuple -> Fraction.
    """
    labels = osc_labels(n)
    idx = {l: i for i, l in enumerate(labels)}

    def _no(m, coeff, acc):
        """Recursively bubble-sort m into normal order."""
        m = list(m)
        reduced = False
        for i in range(len(m) - 1):
            li, lj = m[i], m[j := i + 1]
            if idx[li] > idx[lj]:
                # swap
                pi, pj = osc_parity(li), osc_parity(lj)
                sign = (-1) ** (pi * pj)
                swapped = tuple(m[:i] + [lj, li] + m[j + 1:])
                _no(swapped, coeff * sign, acc)
                if li == lj and pi == 0:
                    # [bi, bi] = 0 for same-type bosons — nothing
                    pass
                if li == lj and pi == 1:
                    # a^2 = 0 for fermion
                    return
                # commutator/anticommutator remainder
                if pi == 0 and pj == 0 and li != lj:
                    # bosons different type: check CCR [bim, bjp] = delta
                    # li > lj in idx means li is "later", e.g. bim after bjp?
                    # CCR: b_i^- * b_j^+ - b_j^+ * b_i^- = delta_{ij}
                    # When we have b_j^+ then b_i^- (i.e., lj=bjp, li=bim going by idx):
                    # check if lj is b?p form and li is b?m
                    def _is_pair(a, b):
                        return (a.startswith("b") and a.endswith("m") and
                                b.startswith("b") and b.endswith("p") and
                                a[:-1] == b[:-1])
                    if _is_pair(li, lj):
                        # b_k^- b_k^+ → 1 + b_k^+ b_k^- (for same k)
                        remainder = tuple(m[:i] + m[j + 1:])
                        _no(remainder, coeff, acc)
                elif pi == 1 and pj == 1:
                    # fermions: {a1p, a1m} = 1 → a1m a1p = 1 - a1p a1m
                    def _is_car_pair(a, b):
                        return a == "a1m" and b == "a1p"
                    if _is_car_pair(li, lj):
                        remainder = tuple(m[:i] + m[j + 1:])
                        _no(remainder, coeff, acc)
                reduced = True
                break
        if not reduced:
            t = tuple(m)
            acc[t] = acc.get(t, Fraction(0)) + coeff

    acc = {}
    _no(tuple(mon), Fraction(1), acc)
    return {k: v for k, v in acc.items() if v != 0}


def gen_realization(n):
    """
    Return dict: generator_label -> dict of monomial->Fraction.
    Using direct oscillator product expansions (no need for full normal ordering
    since we compute brackets directly from algebra rules).
    """
    real = {}
    # Cartan H_1 = a1p*a1m + b1p*b1m
    real["H_1"] = {("a1p", "a1m"): Fraction(1), (f"b1p", f"b1m"): Fraction(1)}
    for k in range(2, n + 1):
        # H_k = b_{k-1}^+ b_{k-1}^- - b_k^+ b_k^-
        real[f"H_{k}"] = {
            (f"b{k-1}p", f"b{k-1}m"): Fraction(1),
            (f"b{k}p", f"b{k}m"): Fraction(-1),
        }
    # H_{n+1} = -b_n^+ b_n^- - 1/2
    real[f"H_{n+1}"] = {
        (f"b{n}p", f"b{n}m"): Fraction(-1),
        (): Fraction(-1, 2),
    }
    # Odd: E_eps1_del{k}_{pp,pm,mp,mm}
    for k in range(1, n + 1):
        real[f"E_eps1_del{k}_pp"] = {("a1p", f"b{k}p"): Fraction(1)}
        real[f"E_eps1_del{k}_pm"] = {("a1p", f"b{k}m"): Fraction(1)}
        real[f"E_eps1_del{k}_mp"] = {("a1m", f"b{k}p"): Fraction(1)}
        real[f"E_eps1_del{k}_mm"] = {("a1m", f"b{k}m"): Fraction(1)}
    # Even non-Cartan
    for k in range(1, n + 1):
        real[f"E_2del{k}_p"] = {(f"b{k}p", f"b{k}p"): Fraction(1)}
        real[f"E_2del{k}_m"] = {(f"b{k}m", f"b{k}m"): Fraction(1)}
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            real[f"E_del{i}_del{j}_pp"] = {(f"b{i}p", f"b{j}p"): Fraction(1)}
            real[f"E_del{i}_del{j}_mm"] = {(f"b{i}m", f"b{j}m"): Fraction(1)}
            real[f"E_del{i}_del{j}_pm"] = {(f"b{i}p", f"b{j}m"): Fraction(1)}
            real[f"E_del{i}_del{j}_mp"] = {(f"b{i}m", f"b{j}p"): Fraction(1)}
    return real


# ---------------------------------------------------------------------------
# Lie superalgebra bracket via oscillator algebra
# ---------------------------------------------------------------------------

def osc_multiply(m1, m2, n):
    """
    Multiply two normal-ordered monomials in the oscillator algebra.
    Returns dict: monomial->Fraction after reducing via CAR/CCR.
    """
    combined = m1 + m2
    return normal_order(combined, n)


def expand_multiply(d1, d2, n):
    """
    Multiply two elements (each given as monomial->coeff dict).
    """
    result = {}
    for m1, c1 in d1.items():
        for m2, c2 in d2.items():
            prod = osc_multiply(m1, m2, n)
            for m, c in prod.items():
                result[m] = result.get(m, Fraction(0)) + c1 * c2 * c
    return {k: v for k, v in result.items() if v != 0}


def graded_bracket(X_real, Y_real, pX, pY, n):
    """
    Compute [X, Y} = XY - (-1)^{pX*pY} YX in the oscillator algebra.
    Returns dict: monomial->Fraction.
    """
    XY = expand_multiply(X_real, Y_real, n)
    YX = expand_multiply(Y_real, X_real, n)
    sign = (-1) ** (pX * pY)
    result = {}
    for m, c in XY.items():
        result[m] = result.get(m, Fraction(0)) + c
    for m, c in YX.items():
        result[m] = result.get(m, Fraction(0)) - sign * c
    return {k: v for k, v in result.items() if v != 0}


def decompose_in_basis(element, realization, basis_all):
    """
    Express element (monomial->coeff dict) as a linear combination of basis generators.
    Returns dict: generator_label -> Fraction, or None if not expressible.
    """
    coeffs = {}
    remaining = dict(element)
    for g in basis_all:
        g_real = realization[g]
        if not g_real:
            continue
        # Find a pivot monomial of g_real that has coeff != 0
        pivot = next(iter(g_real))
        if pivot in remaining and remaining[pivot] != 0:
            c = remaining[pivot] / g_real[pivot]
            if c != 0:
                coeffs[g] = c
                for m, v in g_real.items():
                    remaining[m] = remaining.get(m, Fraction(0)) - c * v
    remaining = {k: v for k, v in remaining.items() if v != 0}
    if remaining:
        return None  # not fully decomposed (should not happen for valid algebra)
    return {k: v for k, v in coeffs.items() if v != 0}


def compute_structure_constants(n, odd, even, realization, parity):
    """
    Compute all non-zero structure constants [X, Y} = sum_Z c_{XY}^Z Z.
    Returns list of dicts.
    """
    basis_all = odd + even
    sc = []
    for i, X in enumerate(basis_all):
        for j, Y in enumerate(basis_all):
            if i > j:
                continue  # use anti-symmetry
            pX, pY = parity[X], parity[Y]
            bracket = graded_bracket(realization[X], realization[Y], pX, pY, n)
            if not bracket:
                continue
            decomp = decompose_in_basis(bracket, realization, basis_all)
            if decomp is None:
                # Try scalar (multiple of identity)
                # Check if bracket is a scalar multiple of ()
                if bracket == {(): list(bracket.values())[0]}:
                    sc.append({
                        "X": X, "Y": Y, "Z": "K",
                        "coeff": str(list(bracket.values())[0]),
                        "sign_rule": "graded"
                    })
                else:
                    raise ValueError(f"Cannot decompose [{X},{Y}] = {bracket}")
            else:
                for Z, c in decomp.items():
                    sc.append({
                        "X": X, "Y": Y, "Z": Z,
                        "coeff": str(c),
                        "sign_rule": "graded"
                    })
    return sc


# ---------------------------------------------------------------------------
# Schema 1 JSON builder
# ---------------------------------------------------------------------------

def build_schema1(n):
    odd, even = build_basis(n)
    basis_all = odd + even
    parity = build_parity(odd, even)
    realization = gen_realization(n)

    sc = compute_structure_constants(n, odd, even, realization, parity)

    even_dim = 2 * n * n + n + 1
    odd_dim = 4 * n
    total_dim = even_dim + odd_dim

    # Build oscillator labels for the 'bosons' key
    boson_labels = [f"b_{k}_{s}" for k in range(1, n + 1) for s in ["p", "m"]]

    # Serializable realization
    def ser_real(d):
        return [{"words": list(m), "coeff": str(c)} for m, c in d.items()]

    gen_real_serial = {g: {"standard_form": ser_real(realization[g]),
                            "parity": parity[g]} for g in basis_all}

    schema = {
        "schema_version": "5.0",
        "algebra": {
            "family": "C",
            "m": 1,
            "n": n,
            "cartan_type": f"C({n+1})",
            "alternative_notation": {
                "osp": f"osp(2|{2*n})",
                "dimension_formula": "osp(2m|2n) with m=1"
            },
            "dimension": {
                "total": total_dim,
                "even": even_dim,
                "odd": odd_dim
            }
        },
        "central_elements": {
            "K": {"label": "K", "parity": 0, "nilpotent": False,
                  "description": "Even central identity; identified with scalar 1."},
            "kappa": {"label": "kappa", "parity": 1, "nilpotent": True,
                      "description": "Odd nilpotent central element; kappa^2=0."}
        },
        "oscillator_generators": {
            "fermions": {
                "m": 1,
                "labels": ["a_1_p", "a_1_m"],
                "parity": 1,
                "description": "Standard fermionic CAR pair a_1^+, a_1^-"
            },
            "bosons": {
                "count": 2 * n,
                "n": n,
                "labels": boson_labels,
                "description": f"Bosonic CCR oscillators b_k^pm for k=1..{n}"
            }
        },
        "oscillator_relations": {
            "standard_fermion_anticommutators": {
                "raising_lowering": "{a_1^-, a_1^+} = 1",
                "same_type_pp": "{a_1^+, a_1^+} = 0",
                "same_type_mm": "{a_1^-, a_1^-} = 0"
            },
            "bosonic_commutators": {
