    for _ in range(len(mon) ** 2 + 10):  # bounded iterations
        new_states = []
        changed = False
        for m, coeff, kappa_c in states:
            swapped = False
            for i in range(len(m) - 1):
                a, b = m[i], m[i + 1]
                ia, ib = order_idx[a], order_idx[b]

                if ia > ib:
                    pa, pb = (1 if a.startswith("a") else 0,
                              1 if b.startswith("b") else 0)  # pb always 0 for bosons
