                            remainder = m[:i] + m[i + 2:]
                    elif pa == 1 and pb == 1:
                        if a == "a1m" and b == "a1p":
                            remainder = m[:i] + m[i + 2:]

                    # Deformed exchange: b_j^s * a_1^sigma → a_1^sigma * b_j^s - gb*kappa
                    # This occurs when a (higher idx) is a boson b_j^s and
                    # b (lower idx) is a fermion a_1^sigma
                    gb_extra = None
