    """Multiply two elements in the deformed algebra, tracking kappa terms."""
    normal_out = {}
    kappa_out = {}

    for m1, c1 in d1.items():
        for m2, c2 in d2.items():
            norm, kappa = _normal_order_deformed(m1 + m2, order_idx, n)
            for m, c in norm.items():
