        for gb_lbl, c in gb_dict.items():
            kappa_br[m][gb_lbl] = kappa_br[m].get(gb_lbl, Fraction(0)) - sign * c
    kappa_br = {k: {g: c for g, c in v.items() if c != 0}
                for k, v in kappa_br.items() if v}

